// OpenAI-Codex_publish_impl: mocked ordering tests; no real network or release.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { stageRelease } from './staged-release-publisher.mjs';
const expected = {tag:'v4.3.21',commitSha:'a'.repeat(40),runId:1,attempt:1};
const names=['Multimedia.Downloader-4.3.21-1.x86_64.rpm','Multimedia.Downloader_4.3.21_aarch64.dmg','Multimedia.Downloader_4.3.21_amd64.AppImage','Multimedia.Downloader_4.3.21_amd64.deb','Multimedia.Downloader_4.3.21_x64-setup.exe','Multimedia.Downloader_4.3.21_x64_en-US.msi'];
function mock() {const calls=[], uploaded=[];const a={calls,verifyAccess:async()=>true,resolveTag:async()=>expected.commitSha,findRelease:async()=>({status:404,complete:true}),validateBuild:async identity=>({verified:true,assets:names.map(name=>({...identity,name,size:1,sha256:createHash('sha256').update('x').digest('hex')}))}),readBytes:async()=>Buffer.from('x'),createDraft:async()=>{calls.push('draft');return{id:7,draft:true,tag:expected.tag}},uploadNew:async x=>{calls.push('upload');uploaded.push({id:uploaded.length+1,name:x.name,size:x.bytes.length,state:'uploaded'});assert.equal(x.overwrite,false)},listAssets:async()=>({complete:true,assets:uploaded}),readUploadedBytes:async()=>Buffer.from('x'),verifyDraft:async()=>true,publishDraft:async()=>{calls.push('publish');return{id:7,draft:false,tag:expected.tag}}};return a;}
test('default cannot write',async()=>{let a=mock();assert.equal((await stageRelease({adapter:a,expected,assets:names.map(name=>({name}))})).ok,false);assert.deepEqual(a.calls,[])});
test('mock success orders draft uploads then publish',async()=>{let a=mock();assert.equal((await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true})).ok,true);assert.deepEqual(a.calls,['draft',...Array(6).fill('upload'),'publish'])});
test('existing release or denied lookup never writes',async()=>{for(const status of [200,403,500]){let a=mock();a.findRelease=async()=>({status,complete:true});assert.equal((await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true})).ok,false);assert.deepEqual(a.calls,[])}});
test('invalid assets and changed tag never write',async()=>{let a=mock();assert.equal((await stageRelease({adapter:a,expected,assets:Array(6).fill({name:'bad'}),enableWrites:true})).ok,false);assert.deepEqual(a.calls,[]);a=mock();a.resolveTag=async()=> 'b'.repeat(40);assert.equal((await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true})).ok,false);assert.deepEqual(a.calls,[])});
test('mismatched readback cannot publish',async()=>{let a=mock();a.readUploadedBytes=async()=>Buffer.from('z');let r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.ok,false);assert.equal(r.draftId,7);assert.equal(a.calls.includes('publish'),false)});
test('untrusted bytes and forged iterator cannot create draft',async()=>{let a=mock();a.readBytes=async()=>Buffer.from('z');let r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.ok,false);assert.deepEqual(a.calls,[]);a=mock();let f=Array(6).fill(null);f[Symbol.iterator]=function*(){yield* names.map(name=>({name}))};r=await stageRelease({adapter:a,expected,assets:f,enableWrites:true});assert.equal(r.ok,false);assert.deepEqual(a.calls,[])});
test('draft response ambiguity preserves id and uncertainty',async()=>{let a=mock();a.createDraft=async()=>({id:7,draft:false,tag:expected.tag});let r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.draftId,7);assert.equal(r.sideEffectUncertain,true);a=mock();a.createDraft=async()=>{throw Error('timeout')};r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.sideEffectUncertain,true)});
test('identity passed to adapter cannot be mutated',async()=>{let a=mock();const initial={...expected};a.validateBuild=async identity=>{try{identity.commitSha='b'.repeat(40)}catch{};return {verified:true,assets:names.map(name=>({...identity,name,size:1,sha256:createHash('sha256').update('x').digest('hex')}))}};const r=await stageRelease({adapter:a,expected:initial,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.ok,true);assert.equal(initial.commitSha,expected.commitSha)});
test('changing draft id getter cannot redirect upload',async()=>{let a=mock(),reads=0;a.createDraft=async()=>({get id(){return ++reads<3?7:99},draft:true,tag:expected.tag});let r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.ok,true);assert.equal(r.draftId,7);assert.equal(reads,1)});
test('mutated manifest cannot bless changed bytes',async()=>{let a=mock(),manifest;const original=a.validateBuild;a.validateBuild=async id=>(manifest=await original(id));a.readBytes=async name=>{manifest.assets.find(x=>x.name===name).sha256=createHash('sha256').update('z').digest('hex');return Buffer.from('z')};let r=await stageRelease({adapter:a,expected,assets:names.map(name=>({name})),enableWrites:true});assert.equal(r.ok,false);assert.deepEqual(a.calls,[])});

